// Normalize Microsoft Graph messages into the Jytte `email` widget
// payload, tagging each sender by domain.
//
// Input : raw Graph message objects from 'Fetch inbox messages' (only
//         the selected fields are present). That node has
//         alwaysOutputData enabled so an empty inbox still triggers
//         this branch - it arrives as a single {} item, dropped by the
//         `id` check below. Without that, an empty inbox would push
//         nothing at all and Jytte's freshness banner would go stale
//         on a perfectly healthy mailbox.
// Output: exactly one item - the body POSTed to /widgets/email/state.

const cfg = $('Config').first().json;

const splitDomains = (raw) =>
  String(raw || '')
    .split(',')
    .map((d) => d.trim().toLowerCase())
    .filter(Boolean);

// tag -> [domains]. Order matters, first match wins, so the
// Computerworld newsletter is classified before the broader buckets.
const tagRules = [
  ['computerworld', splitDomains(cfg.computerworld_sender)],
  ['trustworks', splitDomains(cfg.domains_trustworks)],
  ['dagrofa', splitDomains(cfg.domains_dagrofa)],
];

const tagFor = (domain) => {
  if (!domain) return 'other';
  for (const [tag, domains] of tagRules) {
    // endsWith so a subdomain (nyhedsbrev.computerworld.dk) still
    // matches the parent domain listed in EMAIL_DOMAINS_*.
    if (domains.some((d) => domain === d || domain.endsWith('.' + d))) return tag;
  }
  return 'other';
};

const messages = [];
for (const item of $input.all()) {
  const m = item.json || {};
  if (!m.id) continue; // alwaysOutputData placeholder, not a message

  const addr = String(
    (m.from && m.from.emailAddress && m.from.emailAddress.address) || ''
  ).toLowerCase();
  const domain = addr.includes('@') ? addr.split('@').pop() : '';

  messages.push({
    id: m.id,
    conversation_id: m.conversationId || null,
    subject: m.subject || '',
    from_name: (m.from && m.from.emailAddress && m.from.emailAddress.name) || '',
    from_address: addr,
    domain: domain,
    tag: tagFor(domain),
    received: m.receivedDateTime || null,
    is_read: m.isRead === true,
    has_attachments: m.hasAttachments === true,
    importance: m.importance || 'normal',
    preview: String(m.bodyPreview || '').replace(/\s+/g, ' ').trim().slice(0, 240),
    web_link: m.webLink || null,
    // Annotation signals, passed through raw. Which of them counts as
    // "special" is decided in app/widgets/email/highlight.py, not here.
    categories: Array.isArray(m.categories) ? m.categories : [],
    flag: (m.flag && m.flag.flagStatus) || 'notFlagged',
  });
}

// Graph guarantees no order without $orderby and the node exposes no
// $orderby control, so sort here. Newest first.
messages.sort((a, b) =>
  String(b.received || '').localeCompare(String(a.received || ''))
);

const byTag = { trustworks: 0, dagrofa: 0, computerworld: 0, other: 0 };
let unread = 0;
let annotated = 0;
for (const m of messages) {
  byTag[m.tag] = (byTag[m.tag] || 0) + 1;
  if (!m.is_read) unread += 1;
  if (m.categories.length > 0 || m.flag !== 'notFlagged') annotated += 1;
}

const named = Object.entries(byTag)
  .filter(([tag, n]) => tag !== 'other' && n > 0)
  .map(([tag, n]) => n + ' ' + tag);

const summary =
  messages.length === 0
    ? 'mail: inbox quiet in the lookback window'
    : [
        'mail: ' + messages.length + ' message' + (messages.length === 1 ? '' : 's'),
        unread ? unread + ' unread' : null,
        named.length ? named.join(', ') : null,
      ]
        .filter(Boolean)
        .join(' :: ');

// Top-level `summary` is what POST /widgets/email/state lifts into the
// summary column (app/main.py:230). Timestamps stay ISO 8601 UTC per
// the project convention; the card converts to local in JS.
return [
  {
    json: {
      ready: true,
      source: 'n8n',
      summary: summary,
      fetched_at: new Date().toISOString(),
      lookback_hours: Number(cfg.lookback_hours) || null,
      mailbox: 'inbox',
      counts: { total: messages.length, unread: unread, annotated: annotated, by_tag: byTag },
      messages: messages,
    },
  },
];
